import { expect, test, uniqueName } from "../../fixtures";

const API_TIMEOUT_MS = 60_000;

function yesterdayIso(): string {
  return new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

test.describe("review vendors", () => {
  test(
    "an expired insurance certificate cannot be approved",
    { tag: "@REV-07" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and uploads all three documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV07 Expired Cert"),
          category: "services",
          contact_email: "billing@rev07-expired.test",
        },
      });
      expect(created.status()).toBe(201);
      const vendor = (await created.json()) as { id: string };

      const expiredText = `ACORD CERTIFICATE OF INSURANCE\nPolicy Expiration Date: ${yesterdayIso()}\n`;
      const documents: Array<{ kind: string; name: string; body: string }> = [
        { kind: "w9", name: "w9.txt", body: "FORM W-9\nTaxpayer identification number on file.\n" },
        { kind: "insurance_certificate", name: "insurance.txt", body: expiredText },
        { kind: "contract", name: "contract.txt", body: "MASTER SERVICES AGREEMENT\nTerm: 12 months.\n" },
      ];

      const uploaded: Array<{ id: string }> = [];
      for (const doc of documents) {
        const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: doc.kind,
            file: { name: doc.name, mimeType: "text/plain", buffer: Buffer.from(doc.body) },
          },
        });
        expect(response.status()).toBe(201);
        uploaded.push((await response.json()) as { id: string });
      }

      // Wait for extraction of every document to finish.
      for (const doc of uploaded) {
        await expect
          .poll(
            async () => {
              const res = await member.get(`/api/documents/${doc.id}`);
              return ((await res.json()) as { status: string }).status;
            },
            { timeout: API_TIMEOUT_MS },
          )
          .toBe("extracted");
      }

      // Member submits the vendor, moving it into review.
      const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
      expect(submitted.status()).toBe(200);
      expect(((await submitted.json()) as { status: string }).status).toBe("in_review");

      // Locate the insurance certificate extraction.
      const insuranceDoc = uploaded[1];
      const extractionRes = await member.get(`/api/documents/${insuranceDoc.id}/extraction`);
      expect(extractionRes.status()).toBe(200);
      const extraction = (await extractionRes.json()) as { id: string; status: string };
      expect(extraction.status).toBe("pending_review");

      // Act: reviewer approves the expired insurance certificate.
      const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      expect(decision.status()).toBe(409);
      const body = (await decision.json()) as { error: { code: string } };
      expect(body.error.code).toBe("insurance_expired");
    },
  );
});
